<?php

namespace App\Tests\Pwa;

use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;

/**
 * The PWA files are generated by spomky-labs/pwa-bundle from config/packages/pwa.yaml.
 */
final class PwaTest extends WebTestCase
{
    public function testManifestAndServiceWorkerAreServedAndLinked(): void
    {
        $client = static::createClient();

        $crawler = $client->request('GET', '/hors-ligne');
        self::assertResponseIsSuccessful();
        self::assertSelectorExists('link[rel="manifest"]');
        $manifeste = (string) $crawler->filter('link[rel="manifest"]')->attr('href');

        $client->request('GET', $manifeste);
        self::assertResponseIsSuccessful();
        $json = json_decode((string) $client->getResponse()->getContent(), true, flags: \JSON_THROW_ON_ERROR);
        self::assertSame('Caisson', $json['name']);
        self::assertSame('standalone', $json['display']);
        self::assertNotEmpty($json['icons']);

        $client->request('GET', '/sw.js');
        self::assertResponseIsSuccessful();
        $sw = (string) $client->getResponse()->getContent();
        self::assertStringContainsString('workbox', $sw);
        self::assertStringContainsString('/hors-ligne', $sw, 'precached offline page');
        self::assertStringContainsString("const FEUILLES_DE_ROUTE = 'feuilles-de-route';", $sw, 'custom part appended');
        self::assertStringContainsString("addEventListener('push'", $sw);
    }
}
